132:         private void BtUpdateJson_Click(object sender, EventArgs e)
133:         {
134:             Task.Run(() =>
135:             {
136:                 foreach (Data json in this.JsonList)
137:                 {
138:                     // 1. 读取Json文本
139:                     string content = File.ReadAllText(json.Name);
140: 
141:                     Regex regex = new Regex("type\": \"(?<NameSpace>.+)\\.(?<ClassName>[^\\.]+), AKRS.ZX2200");
142: 
143:                     MatchCollection mc = regex.Matches(content);
144: 
145:                     foreach (Match macth in mc)
146:                     {
147:                         if (macth.Success)
148:                         {
149:                             string nameSpace = macth.Groups["NameSpace"].Value;
150:                             string className = macth.Groups["ClassName"].Value;
151: 
152:                             // 根据ClassName 去找新的命名空间
153:                             ClassNameSpace newClassNameSpace = ClassNameSpaceList.Find(a => a.ClassName == className);
154:                             if (newClassNameSpace == null)
155:                             {
156:                                 this.Invoke(new Action(() =>
157:                                 {
158:                                     this.memoEdit1.AppendText(
159:                                         $"{json.Name}  未能找到{className} 的命名空间----------------------------------------");
160:                                 }));
161:                             }
162:                             else
163:                             {
164:                                 this.Invoke(new Action(() =>
165:                                 {
166:                                     this.memoEdit1.AppendText(
167:                                         $"{json.Name} - {className} : {nameSpace} ---> {newClassNameSpace.NameSpace}");
168:                                 }));
169: 
170:                                 content = content.Replace(nameSpace + "." + className + ", AKRS.ZX2200\"",  newClassNameSpace.NameSpace + "." + className + ", AKRS.ZX2200\"");
171:                             }
172:                         }
173:                     }
174: 
175:                     string filePath = json.Name; // 替换为你的文件路径
176: 
177:                     // 写入并覆盖文件
178:                     File.WriteAllText(filePath, content);
179:                 }
180:             });
181:         }

